//! Running one test: find the gateway, run, clean up.

use std::panic::AssertUnwindSafe;

use futures::FutureExt;

use crate::cli::Cli;
use crate::context::Context;
use crate::error::Result;
use crate::gateway::Gateway;

/// Identity of a test, generated by `#[testkit::test]`.
#[derive(Clone, Copy, Debug)]
pub struct TestInfo {
    /// The function name, which is also the nextest test name.
    pub name: &'static str,
    pub description: &'static str,
}

/// Run a test body against the gateway found by [`Gateway::from_env`].
///
/// Cleanup runs whether the body passes, fails, or panics. The test fails if
/// the body fails, or if cleanup fails after the body passed.
///
/// # Panics
///
/// Panics to fail the test.
pub async fn run<F>(info: TestInfo, body: F)
where
    F: AsyncFnOnce(&mut Context) -> Result,
{
    let name = info.name;
    eprintln!("[{name}] {}", info.description);

    let gateway = Gateway::from_env().unwrap_or_else(|error| panic!("[{name}] {error}"));
    eprintln!("[{name}] {}", gateway.describe());
    let client = gateway
        .connect()
        .await
        .unwrap_or_else(|error| panic!("[{name}] {error}"));
    let mut cx = Context::new(&client, &gateway.workspace, Cli::from_env(&gateway));
    eprintln!("[{name}] run id {}", cx.run_id());

    run_in(name, &mut cx, body).await;
}

/// Run `body` in `cx`, then its cleanup hooks, and fail the test if either
/// failed.
async fn run_in<F>(name: &str, cx: &mut Context, body: F)
where
    F: AsyncFnOnce(&mut Context) -> Result,
{
    let outcome = AssertUnwindSafe(body(cx)).catch_unwind().await;
    let cleanup_failures = cx.cleanup().await;
    for failure in &cleanup_failures {
        eprintln!("[{name}] cleanup failed: {failure}");
    }

    match outcome {
        Err(panic) => std::panic::resume_unwind(panic),
        Ok(Err(error)) => panic!("[{name}] {error}"),
        Ok(Ok(())) => assert!(
            cleanup_failures.is_empty(),
            "[{name}] passed, but cleanup failed: {}",
            cleanup_failures.join("; ")
        ),
    }
}

#[cfg(test)]
mod tests {
    use std::panic::AssertUnwindSafe;
    use std::sync::Arc;
    use std::sync::atomic::{AtomicBool, Ordering};

    use futures::FutureExt;

    use super::run_in;
    use crate::context::Context;
    use crate::error::{Error, Result};

    /// Run `body` the way `#[testkit::test]` does, returning the test's panic
    /// message if it failed.
    async fn outcome<F>(body: F) -> Option<String>
    where
        F: AsyncFnOnce(&mut Context) -> Result,
    {
        let mut cx = Context::unconnected();
        let result = AssertUnwindSafe(run_in("test", &mut cx, body))
            .catch_unwind()
            .await;
        let panic = result.err()?;
        Some(
            panic
                .downcast_ref::<String>()
                .cloned()
                .or_else(|| panic.downcast_ref::<&str>().map(ToString::to_string))
                .unwrap_or_default(),
        )
    }

    /// A cleanup hook that sets the returned marker when it runs.
    fn mark_on_cleanup(cx: &Context) -> Arc<AtomicBool> {
        let marker = Arc::new(AtomicBool::new(false));
        let set = Arc::clone(&marker);
        cx.on_cleanup("set marker", async move || {
            set.store(true, Ordering::SeqCst);
            Ok(())
        });
        marker
    }

    #[tokio::test]
    async fn passing_test_runs_cleanup_and_passes() {
        let mut marker = None;
        let failure = outcome(async |cx: &mut Context| {
            marker = Some(mark_on_cleanup(cx));
            Ok(())
        })
        .await;
        assert_eq!(failure, None);
        assert!(marker.unwrap().load(Ordering::SeqCst));
    }

    #[tokio::test]
    async fn panicking_body_still_runs_cleanup_and_the_test_fails_with_its_panic() {
        let mut marker = None;
        let failure = outcome(async |cx: &mut Context| -> Result {
            marker = Some(mark_on_cleanup(cx));
            panic!("body panic");
        })
        .await;
        assert_eq!(failure.as_deref(), Some("body panic"));
        assert!(marker.unwrap().load(Ordering::SeqCst));
    }

    #[tokio::test]
    async fn failing_body_still_runs_cleanup_and_the_test_fails_with_its_error() {
        let mut marker = None;
        let failure = outcome(async |cx: &mut Context| {
            marker = Some(mark_on_cleanup(cx));
            Err(Error::msg("body error"))
        })
        .await;
        assert_eq!(failure.as_deref(), Some("[test] body error"));
        assert!(marker.unwrap().load(Ordering::SeqCst));
    }

    #[tokio::test]
    async fn failing_cleanup_fails_a_passing_test() {
        let failure = outcome(async |cx: &mut Context| {
            cx.on_cleanup("fails", async || Err(Error::msg("hook error")));
            Ok(())
        })
        .await;
        assert_eq!(
            failure.as_deref(),
            Some("[test] passed, but cleanup failed: fails: hook error")
        );
    }

    #[tokio::test]
    async fn failing_cleanup_does_not_replace_the_body_error() {
        let failure = outcome(async |cx: &mut Context| {
            cx.on_cleanup("fails", async || Err(Error::msg("hook error")));
            Err(Error::msg("body error"))
        })
        .await;
        assert_eq!(failure.as_deref(), Some("[test] body error"));
    }

    #[tokio::test]
    async fn sandbox_tracked_twice_is_deleted_once() {
        // The gateway isn't running, so the delete fails and is reported.
        let failure = outcome(async |cx: &mut Context| {
            cx.track("leaked");
            cx.track("leaked");
            Ok(())
        })
        .await
        .unwrap();
        assert!(
            failure.starts_with("[test] passed, but cleanup failed: delete sandbox leaked: "),
            "{failure}"
        );
        assert_eq!(
            failure.matches("delete sandbox leaked").count(),
            1,
            "{failure}"
        );
    }
}
